    internal static class InstallerText
    {
        private static readonly string[] Codes = { "es", "en", "fr", "de", "it", "pt-BR" };
        private static readonly string[] Names = { "Español", "English", "Français", "Deutsch", "Italiano", "Português (Brasil)" };
        private static readonly Dictionary<string, string[]> Texts = CreateTexts();

        public static string Language { get; private set; }

        static InstallerText()
        {
            Language = DetectLanguage();
        }

        public static string DetectLanguage()
        {
            string language = CultureInfo.CurrentUICulture.Name;
            if (language.StartsWith("pt", StringComparison.OrdinalIgnoreCase)) return "pt-BR";
            foreach (string code in Codes)
                if (language.StartsWith(code, StringComparison.OrdinalIgnoreCase)) return code;
            return "en";
        }

        public static void SetLanguage(string code)
        {
            foreach (string supported in Codes)
                if (String.Equals(code, supported, StringComparison.OrdinalIgnoreCase))
                {
                    Language = supported;
                    return;
                }
            Language = "en";
        }

        public static string[] LanguageCodes { get { return (string[])Codes.Clone(); } }
        public static string[] LanguageNames { get { return (string[])Names.Clone(); } }

        public static string T(string spanish)
        {
            string[] translations;
            if (!Texts.TryGetValue(spanish, out translations)) return spanish;
            int index = Array.IndexOf(Codes, Language);
            return index < 0 ? translations[1] : translations[index];
        }

        public static Dictionary<string, string> ExportTranslations(string code)
        {
            SetLanguage(code);
            int index = Array.IndexOf(Codes, Language);
            Dictionary<string, string> translated = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach (KeyValuePair<string, string[]> entry in Texts)
                translated[entry.Key] = index < 0 ? entry.Value[1] : entry.Value[index];
            return translated;
        }

